// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 minSum, uint256 lockTime, uint256 depositAmount, uint256 collectAmount, bool initBeforeSet) public {
        // Bound parameters to avoid overflow issues
        vm.assume(depositAmount > 0 && depositAmount < type(uint256).max / 2);
        vm.assume(collectAmount < depositAmount);
        vm.assume(lockTime < type(uint256).max / 2);
        vm.assume(minSum < type(uint256).max / 2);

        // Set MinSum to a known value
        if (initBeforeSet) {
            c.Initialized();
        }
        c.SetMinSum(minSum);
        if (!initBeforeSet) {
            c.Initialized();
        }

        // Deposit funds
        (bool success, ) = address(c).call{value: depositAmount}("");
        require(success, "fallback failed");

        // Try to collect - function may revert, we only care about the final MinSum
        // Fast forward time to make unlock possible
        vm.warp(block.timestamp + lockTime + 1);

        // Record MinSum before Collect
        uint256 minSumBefore = c.MinSum();

        // Call Collect
        (bool collectSuccess, ) = address(c).call{value: 0}(
            abi.encodeWithSelector(c.Collect.selector, collectAmount)
        );
        // Ignore collect result

        // The rule: MinSum should never change after initialization
        assertTrue(minSumBefore == c.MinSum(), "MinSum should remain unchanged");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _lockTime, uint256 _putValue, uint256 _collectAmount, uint256 _setMinSum) public {
        // Bound inputs to reasonable ranges
        _lockTime = bound(_lockTime, 0, 365 days);
        _putValue = bound(_putValue, 1, 100 ether);
        _collectAmount = bound(_collectAmount, 1, _putValue);
        _setMinSum = bound(_setMinSum, 0, _collectAmount);

        // Ensure balance is sufficient: put in some value, then advance time past unlock
        vm.deal(address(this), _putValue);
        c.Put{value: _putValue}(_lockTime);
        vm.warp(block.timestamp + _lockTime + 1);

        // Set MinSum low enough to allow collect
        c.SetMinSum(_setMinSum);

        // Now call Initialized to lock further changes (if we were testing reference)
        c.Initialized();

        // Record MinSum before Collect
        uint256 preMinSum = c.MinSum();

        // Try Collect - it may or may not revert
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, _collectAmount));

        // The rule: if Collect succeeded, MinSum is unchanged
        assertTrue(!success || c.MinSum() == preMinSum);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _lockTime, uint256 _am, uint256 _val, uint256 _sendValue) public {
        // Restrict inputs to avoid overflows and ensure Collect can succeed
        vm.assume(_lockTime <= 1000000);
        vm.assume(_am <= 1e18);
        vm.assume(_val <= 1000000);
        vm.assume(_sendValue <= 1e18 && _sendValue <= 1e18);

        // Setup: Initialize the contract and set MinSum and LogFile
        c.SetLogFile(address(0xdead));
        c.SetMinSum(_val);
        c.Initialized();
        uint256 initialMinSum = c.MinSum();

        // Send some value to the contract so balance is >= MinSum
        vm.deal(address(this), _sendValue);
        c.Put{value: _sendValue}(_lockTime);

        // Warp time to unlock
        vm.warp(block.timestamp + _lockTime + 1);

        // Attempt Collect
        bool collectReverted = false;
        try c.Collect(_am) {
            // if Collect succeeds, MinSum must be unchanged
            assertTrue(c.MinSum() == initialMinSum, "MinSum changed after Collect");
        } catch {
            collectReverted = true;
        }
        // If Collect reverts, we don't assert anything (rule only applies when it succeeds)
        // But to satisfy Foundry's requirement of exactly one assertTrue, we add a dummy assertion when reverting
        if (collectReverted) {
            assertTrue(true, "placeholder when Collect reverts");
        }
    }
}

