pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 minSum, uint256 balance, uint256 am) public {
        vm.assume(minSum > 0); // non-zero ensures reference sets MinSum to non-zero; mutant sets to 0
        c.SetMinSum(minSum);
        c.SetLogFile(address(0xdead));
        c.Initialized();

        // Simulate a user with insufficient balance to collect
        address user = address(0x1234);
        vm.deal(user, balance);
        vm.prank(user);
        (bool success, ) = address(c).call{value: balance}(""); // fallback -> Put(0)
        require(success, "Put failed");

        // Try to collect more than balance (or at least >= MinSum won't be satisfied if MinSum > 0)
        vm.prank(user);
        bool reverted = false;
        try c.Collect(am) {} catch { reverted = true; }
        assertTrue(reverted, "Collect should revert due to insufficient balance");

        // After revert, MinSum should equal the set value in reference, but mutant changes to 0
        assertTrue(c.MinSum() == minSum, "MinSum unchanged after revert");
    }
}

