// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _minSum, uint256 _am, uint256 _lockTime, uint256 _value) public {
        // Bound inputs to reasonable values to avoid overflow and satisfy require conditions
        vm.assume(_minSum > 0 && _minSum <= 1000000);
        vm.assume(_am > 0 && _am <= 1000);
        vm.assume(_lockTime >= 1 && _lockTime <= 31536000); // 1 second to 1 year
        vm.assume(_value >= _am && _value <= 1000); // ensure balance can cover _am

        // Set up: initialize contract
        c.SetMinSum(_minSum);
        c.SetLogFile(address(c)); // dummy log address, not used by test
        c.Initialized();

        // Deploy funds to a separate address (avoiding revert on Collect due to insufficient time)
        address user = address(0x123);
        vm.deal(user, _value);
        vm.prank(user);
        c.Put{value: _value}(_lockTime);

        // Record MinSum before Collect
        uint256 minSumBefore = c.MinSum();

        // Attempt Collect with a failing condition: require(acc.balance>=MinSum && acc.balance>=_am && block.timestamp>acc.unlockTime)
        // We'll make it fail by calling from a user with zero balance (or insufficient balance)
        address attacker = address(0x456);
        vm.prank(attacker);
        (bool success, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", _am));
        // The call should revert because attacker has no balance, but we just check state
        // Actually let's make a non-revert call that fails the condition silently: 
        // The require checks balance>=MinSum etc., but if condition false, it just doesn't execute.
        // Since attacker has 0 balance, condition fails and state unchanged.

        // After the call (which did not execute the internal block due to false condition), MinSum should be unchanged
        uint256 minSumAfter = c.MinSum();

        assertTrue(minSumBefore == minSumAfter, "MinSum should remain unchanged when Collect condition fails");
    }
}

