pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    uint initialMinSum;

    function setUp() public { 
        c = new C(); 
        c.SetMinSum(1 ether);
        c.Initialized();
        initialMinSum = 1 ether;
    }

    function testFuzz_property(uint256 lockTime, uint256 deposit, uint256 withdrawAmt, uint256 newMinSum) public {
        // Ensure deposit does not overflow
        vm.assume(deposit > 0 && deposit < type(uint256).max / 2);
        // Ensure withdrawAmt is reasonable
        withdrawAmt = bound(withdrawAmt, 0, deposit);
        // newMinSum can be any value

        // Phase 1: deposit from a user
        address user = address(0x1234);
        vm.deal(user, deposit);
        vm.prank(user);
        c.Put{value: deposit}(lockTime);

        // Phase 2: maybe change MinSum (simulate a second SetMinSum call if newMinSum != initialMinSum)
        if (newMinSum != initialMinSum) {
            c.SetMinSum(newMinSum);
        }

        // Phase 3: call Collect
        vm.warp(block.timestamp + lockTime + 1); // ensure unlock time passed
        vm.prank(user);
        (bool success, ) = address(c).call{gas: 100000}(abi.encodeWithSignature("Collect(uint256)", withdrawAmt));

        // Only consider successful Collect calls
        if (success) {
            // The rule: MinSum must equal the value set by the last SetMinSum call
            uint currentMinSum = c.MinSum();
            assertTrue(currentMinSum == newMinSum, "MinSum changed after successful Collect");
        }
    }
}

