        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", am));
        uint256 balanceAfter = c.Acc(caller).balance;
        // In the reference C (strict >), the withdrawal should revert because timestamp == unlockTime, so balance stays same.
        // In the buggy version (>=), the withdrawal succeeds and balance decreases by am.
        // So the rule: If success occurs, the balance must have decreased.
        assertTrue(!success || balanceAfter < balanceBefore, "Property failed: withdrawal should not succeed at exact unlock time or balance should decrease");
    }
}

