pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 am, uint256 lockTime, uint256 deposit, uint256 minSum) public {
        // Bound inputs to keep computations safe
        am = bound(am, 0, 1000 ether);
        lockTime = bound(lockTime, 0, 365 days);
        deposit = bound(deposit, am, 1000 ether);
        minSum = bound(minSum, 0, am);
        vm.assume(am > 0); // require non-zero withdrawal to trigger balance change

        // Setup: initialize, set minSum, deposit, and set unlock time via block.timestamp + lockTime
        c.SetMinSum(minSum);
        c.Initialized();

        // Simulate user deposits and sets unlockTime = block.timestamp + lockTime
        address user = address(this);
        vm.deal(user, deposit);
        vm.prank(user);
        c.Put{value: deposit}(lockTime);

        // Warp to exactly unlockTime
        vm.warp(block.timestamp + lockTime);

        // Record balance before withdrawal
        (uint256 unlockTimeBefore,) = c.Acc(user);
        // At exact unlockTime, block.timestamp == unlockTimeBefore
        vm.assume(block.timestamp == unlockTimeBefore);

        uint256 balanceBefore = address(user).balance;

        // Attempt Collect at exactly unlockTime
        vm.prank(user);
        (bool success, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", am));

        uint256 balanceAfter = address(user).balance;

        // Rule: If withdrawal succeeds (buggy case), user's external balance increases by am
        // Reference should revert (strict >), so for reference success must be false
        // We assert that the withdrawal does NOT succeed, meaning balance unchanged
        assertTrue(!success || (balanceAfter == balanceBefore));
    }
}
